package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class CharSetUtils_ESTest_test01 extends CharSetUtils_ESTest_scaffolding {

    @Test(timeout = 4000)
    public void test01() throws Throwable {
        final String textWithRepeatedF = "Minimum abbreviation width with offset is %d";
        final String expectedSqueezedText = "Minimum abbreviation width with ofset is %d";

        final String[] characterSet = new String[4];
        characterSet[1] = "ZS[4!;6>G|3UPaJfj";

        final String squeezedText = CharSetUtils.squeeze(textWithRepeatedF, characterSet);

        assertEquals(expectedSqueezedText, squeezedText);
    }
}
